1	import { ButtonGroup } from "@/components/ui/button-group";
2	import {
3	  Tooltip,
4	  TooltipContent,
5	  TooltipTrigger,
6	} from "@/components/ui/tooltip";
7	import { Button } from "@/components/ui/button";
8	import {
9	  ImageDown,
10	  Lock,
11	  LockOpen,
12	  Loader2,
13	  Maximize,
