28	type Props = {
29	  navigationOnly?: boolean;
30	  isConnectionMode?: boolean;
31	  connectionDisabled?: boolean;
32	  onToggleConnectionMode?: () => void;
33	  isSelectionMode?: boolean;
34	  selectionAvailable?: boolean;
35	  onToggleSelectionMode?: () => void;
36	  selectionDisabled?: boolean;
37	};
38	
39	export const FlowPanelControls = ({
40	  navigationOnly = false,
41	  isConnectionMode = false,
42	  connectionDisabled = false,
43	  onToggleConnectionMode,
44	  isSelectionMode = false,
45	  selectionAvailable = false,
46	  onToggleSelectionMode,
47	  selectionDisabled = false,
48	}: Props) => {
49	  const { t } = useTranslation(undefined, {
50	    keyPrefix: "tree-view.controls",
51	  });
52	  const { isLockedScreen, setIsLockedScreen } = useFamilyTreeSettings();
53	  const reactFlow = useReactFlow();
54	  const undo = useMemberStore((s) => s.undo);
55	  const redo = useMemberStore((s) => s.redo);
56	  const undoStack = useMemberStore((s) => s.undoStack);
57	  const redoStack = useMemberStore((s) => s.redoStack);
58	  const { exportImage, isExporting } = useTreeExport();
59	
60	  return (
61	    <ButtonGroup orientation="vertical">
62	      {!navigationOnly && (
63	        <>
64	          <Tooltip>
65	            <TooltipTrigger asChild>
66	              <Button
67	                variant="secondary"
68	                size="icon"
69	                onClick={() => undo()}
70	                disabled={undoStack.length === 0}
71	                aria-label={t("undo")}
72	              >
73	                <Undo2 />
74	              </Button>
75	            </TooltipTrigger>
76	            <TooltipContent side="right">{t("undo")}</TooltipContent>
77	          </Tooltip>
78	          <Tooltip>
79	            <TooltipTrigger asChild>
80	              <Button
81	                variant="secondary"
82	                size="icon"
83	                onClick={() => redo()}
84	                disabled={redoStack.length === 0}
85	                aria-label={t("redo")}
86	              >
87	                <Redo2 />
88	              </Button>
89	            </TooltipTrigger>
90	            <TooltipContent side="right">{t("redo")}</TooltipContent>
91	          </Tooltip>
92	        </>
93	      )}
94	      <Tooltip>
95	        <TooltipTrigger asChild>
96	          <Button
97	            variant="secondary"
98	            size="icon"
99	            onClick={() => reactFlow.zoomIn()}
100	            aria-label={t("zoom-in")}
101	          >
102	            <Plus />
103	          </Button>
104	        </TooltipTrigger>
105	        <TooltipContent side="right">{t("zoom-in")}</TooltipContent>
106	      </Tooltip>
107	      <Tooltip>
108	        <TooltipTrigger asChild>
109	          <Button
110	            variant="secondary"
111	            size="icon"
112	            onClick={() => reactFlow.zoomOut()}
113	            aria-label={t("zoom-out")}
114	          >
115	            <Minus />
116	          </Button>
117	        </TooltipTrigger>
118	        <TooltipContent side="right">{t("zoom-out")}</TooltipContent>
119	      </Tooltip>
120	      <Tooltip>
121	        <TooltipTrigger asChild>
122	          <Button
123	            variant="secondary"
124	            size="icon"
125	            onClick={() => fitViewToAllNodes(reactFlow)}
126	            aria-label={t("fit-view")}
127	          >
128	            <Maximize />
129	          </Button>
130	        </TooltipTrigger>
131	        <TooltipContent side="right">{t("fit-view")}</TooltipContent>
132	      </Tooltip>
133	      <Tooltip>
134	        <TooltipTrigger asChild>
135	          <Button
136	            variant={isConnectionMode ? "default" : "secondary"}
137	            size="icon"
138	            onClick={onToggleConnectionMode}
139	            disabled={connectionDisabled || !onToggleConnectionMode}
140	            aria-label={
141	              isConnectionMode
142	                ? t("disable-connection-mode")
143	                : t("enable-connection-mode")
144	            }
145	          >
146	            <Route />
147	          </Button>
148	        </TooltipTrigger>
149	        <TooltipContent side="right">
150	          {isConnectionMode
151	            ? t("disable-connection-mode")
152	            : t("enable-connection-mode")}
153	        </TooltipContent>
154	      </Tooltip>
155	      {selectionAvailable && (
156	        <Tooltip>
157	          <TooltipTrigger asChild>
158	            <Button
159	              variant={isSelectionMode ? "default" : "secondary"}
160	              size="icon"
161	              onClick={onToggleSelectionMode}
162	              disabled={selectionDisabled || !onToggleSelectionMode}
163	              aria-label={
164	                isSelectionMode
165	                  ? t("disable-selection-mode")
166	                  : t("enable-selection-mode")
167	              }
168	            >
169	              <SquareDashedMousePointer />
170	            </Button>
171	          </TooltipTrigger>
172	          <TooltipContent side="right">
173	            {isSelectionMode
174	              ? t("disable-selection-mode")
175	              : t("enable-selection-mode")}
176	          </TooltipContent>
177	        </Tooltip>
178	      )}
179	      {!navigationOnly && (
180	        <Tooltip>
181	          <TooltipTrigger asChild>
182	            <Button
183	              variant={isLockedScreen ? "default" : "secondary"}
184	              size="icon"
185	              onClick={() => setIsLockedScreen(!isLockedScreen)}
186	              aria-label={
187	                isLockedScreen ? t("unlock-canvas") : t("lock-canvas")
188	              }
189	            >
190	              {isLockedScreen ? <Lock /> : <LockOpen />}
191	            </Button>
192	          </TooltipTrigger>
193	          <TooltipContent side="right">
194	            {isLockedScreen ? t("unlock-canvas") : t("lock-canvas")}
195	          </TooltipContent>
196	        </Tooltip>
197	      )}
198	      <Tooltip>
199	        <TooltipTrigger asChild>
200	          <Button
201	            variant="secondary"
202	            size="icon"
203	            onClick={() => void exportImage()}
204	            disabled={isExporting}
205	            aria-label={t("export-image")}
206	          >
207	            {isExporting ? <Loader2 className="animate-spin" /> : <ImageDown />}
208	          </Button>
209	        </TooltipTrigger>
210	        <TooltipContent side="right">{t("export-image")}</TooltipContent>
211	      </Tooltip>
212	    </ButtonGroup>
213	  );
214	};
