11	} from "@xyflow/react";
12	import { RemoveMemberDialog } from "@/components/shared/dialog/RemoveMemberDialog";
13	import { Button } from "@/components/ui/button";
14	import { useEffect, useMemo, useRef, useState } from "react";
15	import { Member } from "@/types/member";
16	import { NODE_WIDTH, NODE_HEIGHT } from "@/constants";
17	import { useMemberStore } from "@/hooks/useMemberStore";
18	import { useTreeStore, isVirtualId } from "@/hooks/useTreeStore";
19	import { useFamilyTreeSettings } from "@/hooks/useFamilyTreeSettings";
20	import { FlowPanelControls } from "@/components/view/tree-view/FlowPanelControls";
21	import GenerationLines from "@/components/view/tree-view/GenerationLines";
22	import { CanvasSearch } from "@/components/view/tree-view/CanvasSearch";
23	import { EmptyTreeState } from "@/components/view/tree-view/EmptyTreeState";
24	import { MemberControls } from "@/components/view/tree-view/MemberControls";
25	import { ConnectionRelationCard } from "@/components/view/tree-view/ConnectionRelationCard";
26	import { MemberSheet } from "@/components/shared/member-sheet/MemberSheet";
27	import { FamilyNode } from "@/components/view/tree-view/node/FamilyNode";
28	import {
29	  UnionNode,
30	  UNION_NODE_SIZE,
31	} from "@/components/view/tree-view/node/UnionNode";
32	import { AddRelationDialog } from "@/components/view/tree-view/dialog/AddRelationDialog";
33	import { RelationEdge } from "@/components/view/tree-view/edge/RelationEdge";
34	import { useFlowNodes } from "@/hooks/useFlowNodes";
35	import { useFlowEdges } from "@/hooks/useFlowEdges";
36	import { useFlowInteractions } from "@/hooks/useFlowInteractions";
37	import { useUndoRedo } from "@/hooks/useUndoRedo";
38	import { useDerivedFlowView } from "@/hooks/useDerivedFlowView";
39	import { useIsMobile } from "@/hooks/useMobile";
40	import { memberPairKey } from "@/utils/graphUtils";
41	import {
42	  resolveRelationStyle,
43	  relationStyleOverrideFromType,
44	} from "@/utils/relationStyleUtils";
45	import { fitViewToAllNodes } from "@/utils/flowFit";
46	import { useMemberLocator } from "@/hooks/useMemberLocator";
47	import { useConnectionMode } from "@/hooks/useConnectionMode";
48	import { useSelectionMode } from "@/hooks/useSelectionMode";
49	import { SelectionModeController } from "@/components/view/tree-view/SelectionModeController";
50	import { useRelationCreation } from "@/hooks/useRelationCreation";
51	import { usePendingMember } from "@/hooks/usePendingMember";
52	import { useTranslation } from "react-i18next";
53	import { toast } from "sonner";
54	import { useFeature } from "@/hooks/useAuthStore";
55	import { useTaskStore } from "@/hooks/useTaskStore";
56	import { useDeferredStoreLoad } from "@/hooks/useDeferredStoreLoad";
57	import { useMemberSheetStore } from "@/hooks/useMemberSheetStore";
58	import { NoDatabasePlaceholder } from "@/components/layout/NoDatabasePlaceholder";
59	import { PresenceChips } from "@/components/layout/PresenceChips";
60	import {
61	  clearMemberSheetDeepLink,
62	  readMemberSheetDeepLink,
63	} from "@/utils/memberSheetState";
64	import { getGenerationLineGap } from "@/utils/generationLineSpacing";
65	
66	const nodeTypes = { familyMember: FamilyNode, unionNode: UnionNode };
67	const edgeTypes = { relation: RelationEdge };
68	
69	interface FlowPanelProps {
70	  // Chromeless, purely-visual rendering for the public read-only tree view:
71	  // no member sheet, no edit dialogs, no node action buttons.
72	  publicView?: boolean;
73	}
74	
75	// Stable reference for "no connection-path highlight". findConnectionPathHighlight
76	// returns a fresh (often empty) Set on every members change; passing that straight
77	// into useFlowEdges would re-derive viewEdges from a still-stale baseEdges during the
78	// async worker round-trip, briefly re-adding a just-deleted edge (a one-frame flicker).
79	// An empty highlight set has no visual effect, so we collapse it to one shared instance.
80	const EMPTY_EDGE_KEYS: ReadonlySet<string> = new Set<string>();
81	
82	export const FlowPanel = ({ publicView = false }: FlowPanelProps = {}) => {
83	  const { t } = useTranslation();
84	  const treeLinksEnabled = useFeature("tree_links");
85	  const taskRestrictions = useTreeStore((s) => s.selectedTree?.restrictions);
86	  const tasksEnabled =
87	    useFeature("research_tasks") && !taskRestrictions?.includes("tasks");
88	  const { refreshTasks, initialized: tasksInitialized } = useTaskStore();
89	  // Open-task node indicators need the task list; skip on public trees where
90	  // the task endpoints require authentication.
91	  useDeferredStoreLoad(
92	    tasksInitialized || !tasksEnabled || publicView,
93	    refreshTasks,
94	  );
95	  const activeTree = useTreeStore((s) => s.selectedTree);
96	  const openTreeAndLocateMember = useTreeStore(
97	    (s) => s.openTreeAndLocateMember,
98	  );
99	  const savedMemberSheetState = useMemberSheetStore((s) =>
100	    activeTree?.id ? s.openSheets[activeTree.id] : undefined,
101	  );
102	  const setOpenSheet = useMemberSheetStore((s) => s.setOpenSheet);
103	  const clearOpenSheet = useMemberSheetStore((s) => s.clearOpenSheet);
104	  const availableTreeCount = useTreeStore(
105	    (s) => s.trees.length + s.virtualViews.length,
106	  );
107	  const isMobile = useIsMobile();
108	  const {
109	    members,
110	    removeMember,
111	    updateLayout,
112	    windowed,
113	    focusRootId,
114	    neighborhoodTruncated,
115	    totalMemberCount,
116	    setFocusRoot,
117	    pendingLocateMemberId,
118	    setPendingLocateMemberId,
119	  } = useMemberStore();
120	  const canWrite = activeTree?.role !== "viewer";
121	  const isVirtualView = !!activeTree?.id && isVirtualId(activeTree.id);
122	  const isCanvasReadOnly = isMobile || !canWrite;
123	  // Virtual views allow dragging even though canWrite is false (role: "viewer").
124	  // Positions are persisted independently in VirtualViewPosition.
125	  const canDragLayout = !isMobile && (canWrite || isVirtualView);
126	  useUndoRedo(!isCanvasReadOnly);
127	  const { isReady } = useTreeStore();
128	
129	  const {
130	    edgeType,
131	    isLockedScreen,
132	    visibleRelationTypes,
133	    viewports,
134	    setViewport,
135	    generationLineGaps,
136	  } = useFamilyTreeSettings();
137	  const DEFAULT_VIEWPORT = { x: 0, y: 0, zoom: 1 };
138	  const viewport = (activeTree && viewports[activeTree.id]) ?? DEFAULT_VIEWPORT;
139	  const generationLineGap = getGenerationLineGap(
140	    activeTree ? generationLineGaps[activeTree.id] : undefined,
141	  );
142	  const [rfInstance, setRfInstance] = useState<ReactFlowInstance | null>(null);
143	  const [nodes, setNodes] = useState<Node[]>([]);
144	  const [edges, setEdges] = useState<Edge[]>([]);
145	  const [membersToDelete, setMembersToDelete] = useState<Member[]>([]);
146	  const [selectedNodes, setSelectedNodes] = useState<Node[]>([]);
147	
148	  // --- Extracted hooks ---
149	  const locator = useMemberLocator(members, rfInstance);
150	
151	  // Center the counterpart after navigating into a linked tree: consume the
152	  // one-shot locate request once the member shows up in the loaded set. In
153	  // windowed mode the counterpart may lie outside the current neighborhood —
154	  // re-focus the window on it once and locate after the reload.
155	  const attemptedLinkedFocusRef = useRef<string | null>(null);
156	  const consumedLocateRef = useRef<string | null>(null);
157	  useEffect(() => {
158	    if (!pendingLocateMemberId) {
159	      consumedLocateRef.current = null;
160	      return;
161	    }
162	    const target = members.find((m) => m.id === pendingLocateMemberId);
163	    if (target) {
164	      // Wait until the canvas is fully up before consuming the request: on a
165	      // fresh mount (e.g. arriving from the map view) rfInstance is null,
166	      // the nodes land a couple of commits later, and React Flow applies its
167	      // initial viewport only once it is measured — centering before that
168	      // gets silently overridden. viewportInitialized flips after that
169	      // initial viewport is in; the `nodes` dep re-runs this until then.
170	      if (!rfInstance?.viewportInitialized || !rfInstance.getNode(target.id))
171	        return;
172	      // Commits queued behind the mount burst still carry the pre-consumption
173	      // store snapshot — don't re-center for each of them.
174	      if (consumedLocateRef.current === pendingLocateMemberId) return;
175	      consumedLocateRef.current = pendingLocateMemberId;
176	      attemptedLinkedFocusRef.current = null;
177	      setPendingLocateMemberId(null);
178	      locator.locateMember(target);
179	      return;
180	    }
181	    if (members.length === 0) return; // still loading
182	    if (windowed && attemptedLinkedFocusRef.current !== pendingLocateMemberId) {
183	      attemptedLinkedFocusRef.current = pendingLocateMemberId;
184	      void setFocusRoot(pendingLocateMemberId);
185	      return;
186	    }
187	    // Fully loaded (or window already re-focused) and still absent: the
188	    // counterpart no longer exists — drop the request.
189	    attemptedLinkedFocusRef.current = null;
190	    setPendingLocateMemberId(null);
191	  }, [
192	    pendingLocateMemberId,
193	    members,
194	    windowed,
195	    setFocusRoot,
196	    setPendingLocateMemberId,
197	    locator,
198	    rfInstance,
199	    nodes,
200	  ]);
201	
202	  // Mutual exclusion between connection mode and selection mode: entering one
203	  // exits the other. `connection` is instantiated first, so its
204	  // onEnterConnectionMode callback can't close over `selection` directly
205	  // (TDZ / stale closure). Instead it reads the latest selection-mode state
206	  // and toggle function through a ref that is kept up to date every render.
207	  const exitSelectionRef = useRef<{
208	    isSelectionMode: boolean;
209	    toggleSelectionMode: () => void;
210	  } | null>(null);
211	
212	  const connection = useConnectionMode(members, () => {
213	    setSelectedNodes([]);
214	    if (exitSelectionRef.current?.isSelectionMode) {
215	      exitSelectionRef.current.toggleSelectionMode();
216	    }
217	  });
218	
219	  const selection = useSelectionMode(() => {
220	    if (connection.isConnectionMode) connection.toggleConnectionMode();
221	  });
222	
223	  useEffect(() => {
224	    exitSelectionRef.current = selection;
225	  });
226	
227	  // Clear the marquee selection when selection mode is exited (native RF
228	  // selection + our selectedNodes mirror). Skip the initial mount so this
229	  // doesn't run before the user has ever entered selection mode.
230	  const prevIsSelectionModeRef = useRef(false);
231	  useEffect(() => {
232	    if (prevIsSelectionModeRef.current && !selection.isSelectionMode) {
233	      setSelectedNodes([]);
234	      setNodes((ns) =>
235	        ns.map((n) => (n.selected ? { ...n, selected: false } : n)),
236	      );
237	    }
238	    prevIsSelectionModeRef.current = selection.isSelectionMode;
239	  }, [selection.isSelectionMode]);
240	
241	  const inSelectionMode = selection.isSelectionMode;
242	
243	  const relation = useRelationCreation();
244	
245	  const pending = usePendingMember({
246	    onHorizontalRelationReady: relation.startHorizontalRelation,
247	  });
248	  const memberSheetDeepLink = useMemo(readMemberSheetDeepLink, []);
249	  const consumedMemberSheetDeepLinkRef = useRef(false);
250	  const attemptedMemberSheetRestoreRef = useRef<string | null>(null);
251	
252	  useEffect(() => {
253	    const deepLinkState = consumedMemberSheetDeepLinkRef.current
254	      ? undefined
255	      : memberSheetDeepLink;
256	    const requestedState = deepLinkState ?? savedMemberSheetState;
257	    const treeId = activeTree?.id;
258	    if (publicView || !requestedState || !treeId || pending.editingMemberId) {
259	      return;
260	    }
261	
262	    const savedMember = members.find(
263	      (member) => member.id === requestedState.memberId,
264	    );
265	    if (savedMember) {
266	      attemptedMemberSheetRestoreRef.current = null;
267	      setOpenSheet(treeId, requestedState);
268	      if (deepLinkState) {
269	        consumedMemberSheetDeepLinkRef.current = true;
270	        clearMemberSheetDeepLink();
271	      }
272	      pending.setEditingMemberId(savedMember.id);
273	      pending.setIsEditMode(requestedState.mode === "edit");
274	    } else if (
275	      isReady &&
276	      windowed &&
277	      attemptedMemberSheetRestoreRef.current !== requestedState.memberId
278	    ) {
279	      attemptedMemberSheetRestoreRef.current = requestedState.memberId;
280	      void setFocusRoot(requestedState.memberId);
281	    } else if (isReady) {
282	      clearOpenSheet(treeId);
283	      if (deepLinkState) {
284	        consumedMemberSheetDeepLinkRef.current = true;
285	        clearMemberSheetDeepLink();
286	      }
287	    }
288	  }, [
289	    activeTree?.id,
290	    clearOpenSheet,
291	    isReady,
292	    memberSheetDeepLink,
293	    members,
294	    pending.editingMemberId,
295	    pending.setEditingMemberId,
296	    pending.setIsEditMode,
297	    publicView,
298	    savedMemberSheetState,
299	    setOpenSheet,
300	    setFocusRoot,
301	    windowed,
302	  ]);
303	
304	  // --- Unions, edges & visibility — computed off the main thread ---
305	  const { unions, baseEdges, hiddenNodeIds } = useDerivedFlowView(
306	    members,
307	    visibleRelationTypes,
308	    edgeType,
309	  );
310	
311	  // Resolve each union dot's colour the same way edges are styled: the
312	  // relation-type default merged with the admin override. Without this the
313	  // dot ignores configured colours (the edges are styled in the worker).
314	  const relationTypes = useTreeStore((s) => s.relationTypes);
315	  const resolveUnionColor = useMemo(() => {
316	    const byId = new Map(relationTypes.map((rt) => [rt.id, rt]));
317	    return (relationType?: string): string => {
318	      const rt = relationType ? byId.get(relationType) : undefined;
319	      return resolveRelationStyle(
320	        relationType ?? "",
321	        rt ? relationStyleOverrideFromType(rt) : undefined,
322	      ).stroke;
323	    };
324	  }, [relationTypes]);
325	
326	  // Use `nodes` (local state, updates on every drag frame) rather than `members`
327	  // (store, lags by the debounce) so union dots track their parents in real-time.
328	  // Carry the measured height: card height varies with content (e.g. source-tree
329	  // badges in virtual views), and the side handles sit at the measured mid-height.
330	  const nodePositions = useMemo(
331	    () =>
332	      new Map(
333	        nodes.map((n) => [
334	          n.id,
335	          {
336	            x: n.position.x,
337	            y: n.position.y,
338	            height: n.measured?.height ?? NODE_HEIGHT,
339	          },
340	        ]),
341	      ),
342	    [nodes],
343	  );
344	
345	  const unionNodes = useMemo<Node[]>(
346	    () =>
347	      unions
348	        .filter(
349	          (u) =>
350	            nodePositions.has(u.partner1Id) && nodePositions.has(u.partner2Id),
351	        )
352	        .map((u) => {
353	          const p1 = nodePositions.get(u.partner1Id)!;
354	          const p2 = nodePositions.get(u.partner2Id)!;
355	          const unionMemberPairHighlighted =
356	            connection.connectionPath.edgeKeys.has(
357	              memberPairKey(u.partner1Id, u.partner2Id),
358	            );
359	          const unionChildHighlighted = u.childIds.some((childId) =>
360	            [u.partner1Id, u.partner2Id].some((parentId) =>
361	              connection.connectionPath.edgeKeys.has(
362	                memberPairKey(parentId, childId),
363	              ),
364	            ),
365	          );
366	          const isUnionConnectionPath =
367	            connection.hasConnectionPath &&
368	            (unionMemberPairHighlighted || unionChildHighlighted);
369	
370	          return {
371	            id: u.id,
372	            type: "unionNode",
373	            // Hide the union dot when a partner is collapsed away, so it does
374	            // not linger with dangling connector edges.
375	            hidden:
376	              hiddenNodeIds.has(u.partner1Id) ||
377	              hiddenNodeIds.has(u.partner2Id),
378	            position: {
379	              x: (p1.x + p2.x) / 2 + NODE_WIDTH / 2 - UNION_NODE_SIZE / 2,
380	              // Center the dot at the average mid-height of the partner cards
381	              // (where their side handles sit) so the connector edges run level.
382	              y:
383	                (p1.y + p1.height / 2 + p2.y + p2.height / 2) / 2 -
384	                UNION_NODE_SIZE / 2,
385	            },
386	            data: {
387	              ...u,
388	              color: resolveUnionColor(u.relationType),
389	              isConnectionPath: isUnionConnectionPath,
390	              isConnectionDimmed:
391	                connection.isConnectionMode &&
392	                connection.hasConnectionPath &&
393	                !isUnionConnectionPath,
394	              onAddChildToUnion: pending.onAddChildToUnion,
395	              isReadOnly: isCanvasReadOnly,
396	            },
397	            draggable: false,
398	            selectable: false,
399	            focusable: false,
400	            // Pre-set dimensions so React Flow skips its ResizeObserver
401	            // measurement cycle and renders the node visible immediately.
402	            width: UNION_NODE_SIZE,
403	            height: UNION_NODE_SIZE,
