36	export const test = base.extend<E2EFixtures>({
37	  // The SPA reads its language from localStorage and otherwise defaults to
38	  // German; force English so locale-dependent text selectors are reliable.
39	  // (Playwright's `locale` option only sets navigator.language, which the app
40	  // ignores.) Applies to every test's `page`, including `adminPage`.
41	  page: async ({ page }, use) => {
42	    await page.addInitScript(() => {
43	      try {
