1	/**
2	 * Low-level API helper for E2E tests.
3	 * All calls go through the backend REST API so tests can arrange state without
4	 * driving the UI.  Pass a JWT token obtained from apiLogin().
5	 */
6	
7	import { API_URL } from "../playwright.config";
8	
9	export interface ApiClient {
10	  token: string;
11	  get<T = unknown>(path: string): Promise<T>;
12	  post<T = unknown>(path: string, body?: unknown): Promise<T>;
13	  patch<T = unknown>(path: string, body: unknown): Promise<T>;
14	  delete(path: string): Promise<void>;
15	}
16	
17	export async function apiLogin(
18	  username: string,
19	  password: string,
20	): Promise<string> {
21	  const res = await fetch(`${API_URL}/auth/login`, {
22	    method: "POST",
23	    headers: { "Content-Type": "application/json" },
24	    body: JSON.stringify({ username, password }),
25	  });
26	  if (!res.ok) {
27	    const text = await res.text();
28	    throw new Error(`Login failed ${res.status}: ${text}`);
29	  }
30	  const data = (await res.json()) as { access_token?: string };
31	  if (!data.access_token) throw new Error("Login returned no access_token");
32	  return data.access_token;
33	}
34	
35	export async function waitForJob(
36	  token: string,
37	  jobId: string,
38	  maxAttempts = 30,
39	  intervalMs = 1000,
40	): Promise<string> {
41	  for (let attempt = 0; attempt < maxAttempts; attempt++) {
42	    const res = await fetch(`${API_URL}/jobs/${jobId}`, {
43	      headers: { Authorization: `Bearer ${token}` },
44	    });
45	    if (!res.ok) throw new Error(`GET /jobs/${jobId} → ${res.status}`);
46	    const job = (await res.json()) as {
47	      status: string;
48	      result_tree_id?: string;
49	      error?: string;
50	    };
51	    if (job.status === "done" && job.result_tree_id) return job.result_tree_id;
52	    if (job.status === "failed") throw new Error(`Job failed: ${job.error}`);
53	    await new Promise((resolve) => setTimeout(resolve, intervalMs));
54	  }
55	  throw new Error(
56	    `Job ${jobId} did not complete after ${maxAttempts} attempts`,
57	  );
58	}
59	
60	export function makeApiClient(token: string): ApiClient {
61	  const headers = () => ({
62	    "Content-Type": "application/json",
63	    Authorization: `Bearer ${token}`,
64	  });
