import { chromium } from "playwright";
import { randomUUID } from "crypto";

const BASE_URL = "http://localhost:1420";
const API_URL = "http://localhost:8000/api";
const ADMIN_USERNAME = "admin";
const ADMIN_PASSWORD = "change-me";
const OUT_DIR =
  "/tmp/claude-1000/-home-codex-projects-family-tree/38848118-c253-40d5-b99f-05a6db20f2ff/scratchpad/screenshots";

async function apiLogin() {
  const res = await fetch(`${API_URL}/auth/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username: ADMIN_USERNAME, password: ADMIN_PASSWORD }),
  });
  if (!res.ok) throw new Error(`login failed ${res.status}: ${await res.text()}`);
  const data = await res.json();
  return data.access_token;
}

async function apiPost(token, path, body) {
  const res = await fetch(`${API_URL}${path}`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify(body),
  });
  if (!res.ok) throw new Error(`POST ${path} failed ${res.status}: ${await res.text()}`);
  return res.json();
}

async function main() {
  const token = await apiLogin();
  const treeId = randomUUID();
  const treeName = `Toolbar-Screens-${treeId.slice(0, 8)}`;
  await apiPost(token, "/trees", { id: treeId, name: treeName });

  const alice = await apiPost(token, `/trees/${treeId}/members`, {
    id: randomUUID(),
    firstName: "Alice",
    lastName: "Smith",
    gender: "f",
    dateOfBirth: "1980-01-01",
  });
  const bob = await apiPost(token, `/trees/${treeId}/members`, {
    id: randomUUID(),
    firstName: "Bob",
    lastName: "Smith",
    gender: "m",
    dateOfBirth: "1978-06-15",
  });
  await apiPost(token, `/trees/${treeId}/relations`, {
    from_member_id: alice.id,
    to_member_id: bob.id,
    relation_type: "partner",
  });
  const charlie = await apiPost(token, `/trees/${treeId}/members`, {
    id: randomUUID(),
    firstName: "Charlie",
    lastName: "Smith",
    gender: "m",
    dateOfBirth: "2005-03-20",
  });
  await apiPost(token, `/trees/${treeId}/relations`, {
    from_member_id: alice.id,
    to_member_id: charlie.id,
    relation_type: "parent",
  });

  const browser = await chromium.launch({ args: ["--no-sandbox"] });

  for (const theme of ["light", "dark"]) {
    const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
    const page = await context.newPage();
    await page.addInitScript((t) => {
      try {
        localStorage.setItem("i18nextLng", "en");
        localStorage.setItem("theme", t);
      } catch {
        /* ignore */
      }
    }, theme);
    await page.route("**/api/users/me/preferences/tutorial", async (route) => {
      if (route.request().method() === "GET") {
        await route.fulfill({ json: { completed: true } });
      } else {
        await route.continue();
      }
    });
    await page.route("**/api/users/me/preferences/whats-new", async (route) => {
      if (route.request().method() === "GET") {
        await route.fulfill({ json: { last_read_version: "dev" } });
      } else {
        await route.continue();
      }
    });
    await page.route("**/api/sse/events*", (route) => route.abort());

    await page.goto(BASE_URL);
    await page.locator("#username").waitFor({ state: "visible", timeout: 15000 });
    await page.locator("#username").fill(ADMIN_USERNAME);
    await page.locator("#password").fill(ADMIN_PASSWORD);
    await page.locator('button[type="submit"]').click();
    await page.locator("#username").waitFor({ state: "hidden", timeout: 15000 });

    // Navigate directly to the seeded tree's canvas view.
    await page.goto(`${BASE_URL}/tree/${treeId}`);
    await page.waitForTimeout(1500);
    await page.locator(".ft-tree-canvas").waitFor({ state: "visible", timeout: 15000 });
    await page.waitForTimeout(800);

    await page.screenshot({ path: `${OUT_DIR}/toolbar-full-${theme}.png` });

    // Also select a node so the "focus-here" style conditional states render
    // consistently, then screenshot cropped to the two control stacks.
    const canvasBox = await page.locator(".ft-tree-canvas").boundingBox();
    if (canvasBox) {
      await page.screenshot({
        path: `${OUT_DIR}/toolbar-left-${theme}.png`,
        clip: {
          x: canvasBox.x,
          y: canvasBox.y + canvasBox.height - 420,
          width: 260,
          height: 420,
        },
      });
      await page.screenshot({
        path: `${OUT_DIR}/toolbar-right-${theme}.png`,
        clip: {
          x: canvasBox.x + canvasBox.width - 260,
          y: canvasBox.y + canvasBox.height - 420,
          width: 260,
          height: 420,
        },
      });
    }

    // Open the left "more" menu and screenshot it open.
    const leftMore = page.getByRole("button", { name: "More actions" }).first();
    if (await leftMore.count()) {
      await leftMore.click();
      await page.waitForTimeout: 300 === undefined ? null : await page.waitForTimeout(300);
      await page.screenshot({ path: `${OUT_DIR}/toolbar-left-menu-${theme}.png` });
      await page.keyboard.press("Escape");
    }

    await context.close();
  }

  await browser.close();
  console.log("done");
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

